import json,uuid
from pathlib import Path
root=Path(__file__).parent
bank=json.loads((root/'questions.json').read_text())
by={x['family_id']:x for x in bank}
items=[
('demo-clinic-stairs','equity-transport','კლინიკა უფასოა, მაგრამ შესასვლელთან კიბე ეტლით მოსარგებლეს აფერხებს. რომელი ნაბიჯი აგვარებს აღწერილ ბარიერს?',['უფრო დიდი ლოგო','ადაპტირებული შესასვლელის მოწყობა','მეტი სარეკლამო ბროშურა','მხოლოდ უფასო ფასის განმეორება'],1,'მომსახურების რეალური წვდომა ფიზიკურ ხელმისაწვდომობასაც მოითხოვს. ფასი ამ სცენარში ერთადერთი ბარიერი არ არის.'),
('demo-local-council','phc-community-voice','სოფელში ახალი ჯანმრთელობის პროგრამა იგეგმება. რომელ კითხვაზე მოსახლეობის მოსმენა დაეხმარება დაგეგმვას?',['ვინ აირჩევს ოფისის ფერს?','რამდენი ლოგო უნდა დაიბეჭდოს?','რომელი საჭიროებები და მომსახურებაზე წვდომის ბარიერები გაქვთ?','როგორ ავკრძალოთ უკუკავშირი?'],2,'თემის მონაწილეობა ეხმარება პროგრამას ადამიანების რეალურ საჭიროებებზე ორიენტირებაში.'),
('demo-readable-poster','literacy-accessible-message','ინსტრუქცია მნიშვნელოვანია, მაგრამ დაწერილია ძალიან წვრილი შრიფტით და რთული წინადადებებით. რას გააუმჯობესებდი?',['შრიფტს კიდევ უფრო შევამცირებდი','ბროშურას ფასს გავუზრდიდი','პაციენტებს ვეტყოდი აღარ ეკითხათ','გამოკვეთილ, წაკითხვად და გასაგებ ტექსტს შევქმნიდი'],3,'ინფორმაციის ხელმისაწვდომობა და გაგება ორგანიზაციული ჯანმრთელობის წიგნიერების ნაწილია.'),
('demo-research-post','literacy-appraisal','სოციალურ ქსელში წერია: „ერთმა კვლევამ ყველაფერი საბოლოოდ დაამტკიცა“. რა კითხვა დაგეხმარება მტკიცებულების შეფასებაში?',['ვისზე, როგორ და რა შეზღუდვებით ჩატარდა კვლევა?','რამდენი ემოჯი აქვს პოსტს?','რამდენად ხმამაღალია სათაური?','მეგობარმა უკვე გააზიარა?'],0,'კრიტიკული შეფასება მოითხოვს წყაროსა და მტკიცებულების კონტექსტის შესწავლას.'),
('demo-commute-movement','activity-domestic','ადამიანი სამსახურისკენ ფეხით მიდის და ამბობს, ეს აქტივობა არ არის, რადგან სპორტი არ ჰქვია. რომელი პასუხია სწორი?',['აქტივობას აუცილებლად მედალი სჭირდება','გადაადგილებისას სიარულიც ფიზიკური აქტივობაა','აქტივობას მხოლოდ დარბაზი განსაზღვრავს','სიარული მხოლოდ მჯდომარე ქცევაა'],1,'WHO-ს განმარტება მოიცავს გადაადგილების დროს მოძრაობასაც.'),
('demo-menu-label','diet-hidden-salt','ორ მსგავს მზა პროდუქტს შორის არჩევანისას მარილის შემცირება გინდა. რას შეადარებდი?',['შეფუთვის ფერს','პროდუქტის სახელის სიგრძეს','ნატრიუმის შემცველობას ერთნაირ რაოდენობაში','მხოლოდ რეკლამის პოპულარობას'],2,'შედარება ერთსა და იმავე რაოდენობაზე უნდა მოხდეს, რათა განსხვავებული პორციები შეცდომაში არ შეგიყვანოს.'),
('demo-workplace-smoke','tobacco-shs','ოფისში რამდენიმე ადამიანი ეწევა, სხვები კი არა. რომელი ღონისძიება იცავს არამწეველებს კვამლისგან?',['კვამლის უსიამოვნო სუნის დამალვა','მხოლოდ ოთახის სახელის შეცვლა','არამწეველებისთვის პრობლემის იგნორირება','თამბაქოს კვამლისგან თავისუფალი სამუშაო სივრცე'],3,'არამწეველებსაც აზიანებს მეორეული კვამლი; მისი უსაფრთხო ზღვარი არ არსებობს.'),
('demo-water-access','water-managed','ოჯახს ონკანის წყალი სახლში აქვს, მაგრამ შემოწმებამ დაბინძურება აჩვენა. ეს უკვე უსაფრთხოდ მართული მომსახურებაა?',['არა — ადგილზე ყოფნა უსაფრთხოებას ვერ ანაცვლებს','დიახ — ონკანის არსებობა ყველაფერს ადასტურებს','დიახ — დაბინძურება განსაზღვრებაში არ შედის','დიახ — წყლის გამოყენებას მნიშვნელობა არ აქვს'],0,'უსაფრთხოდ მართული წყალი უნდა იყოს ხელმისაწვდომი და დაბინძურებისგან თავისუფალი.'),
('demo-speed-injuries','road-system','ქალაქს სურს სკოლასთან საგზაო ტრავმების პრევენცია. რომელია გარემოზე მიმართული მოქმედება?',['მხოლოდ შემთხვევების შემდეგ პოსტის დაწერა','სიჩქარის შემზღუდველი საგზაო ღონისძიებები','სიჩქარის როლის უარყოფა','ყველა შეცდომის ბავშვებისთვის დაბრალება'],1,'სიჩქარის მართვა და უსაფრთხო ინფრასტრუქტურა უსაფრთხო საგზაო სისტემის ნაწილია.'),
('demo-risk-rates','risk-denominator','გამოგონილ ჯგუფში 10 ავადმყოფია 50 ადამიანიდან, მეორეში კი 10 — 100 ადამიანიდან. რომელ ჯგუფშია ავადმყოფობის წილი მეტი?',['ორივეში თანაბარია, რადგან 10=10','მეორეში: 100 მეტია 50-ზე','პირველში: 20%, მეორეში 10%','მონაცემები ვერასდროს შეედრება'],2,'წილი დამოკიდებულია როგორც შემთხვევების, ისე ჯგუფის მთლიან რაოდენობაზე. მონაცემები გამოგონილია.'),
]
out=[]
for fid,base,prompt,opts,ans,exp in items:
 x=by[base].copy(); x.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL,'public-health-challenge:'+fid)),family_id=fid,prompt=prompt,options=opts,answer_index=ans,explanation=exp,status='draft',demo_only=True)
 out.append(x)
assert len(out)==10
assert not set(x['id'] for x in out)&set(x['id'] for x in bank)
assert not set(x['family_id'] for x in out)&set(x['family_id'] for x in bank)
(root/'demo-questions.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print('10 distinct demo-only drafts saved; excluded from ranked bank')
